    if (t < 0.7) return mix(vec3(0.0, 0.65, 0.75), vec3(0.05, 0.85, 0.35), (t - 0.3) / 0.4);
    return mix(vec3(0.05, 0.85, 0.35), vec3(0.75, 1.0, 0.2), (t - 0.7) / 0.3);
